INSERT INTO products (id, image, link, text, text_de, title, title_de) VALUES (10, 'sortiment/okrasne-kamenivo.webp', '/sortiment/okrasne-kamenivo', 'Kamenivo stavební frakce', 'Bauschotter-Körnung', 'Okrasné kamenivo', 'Ziersteine');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (16, 1, 'palivove', 'Lehké smrkové dřevo ideální pro rychlé vytopení krbů a kamen, snadno chytá plamen. Výhřevnost cca 1500–1700 kWh/m³, hoří 1–2 hodiny.', 'Leichtes Fichtenholz, ideal für schnelles Aufheizen von Kaminen und Öfen, fängt leicht Feuer. Heizwert ca. 1500–1700 kWh/m³, brennt 1–2 Stunden.', 'Doporučeno sušit 6–12 měsíců na suchém, větraném místě.', 'Empfohlene Trocknungszeit 6–12 Monate an einem trockenen, gut belüfteten Ort.', 'soft', 'Smrk palivové dřevo', 'Fichte Brennholz', 'smrk', 0, 'Měkké palivové dřevo', 'Weiches Brennholz', 'firewood', 'Smrk', 'Fichte', 'Měkké palivové dřevo', 'Weiches Brennholz', '/img/eshop/smrk.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (17, 1, 'palivove', 'Dubové dřevo s vysokou výhřevností a dlouhou dobou hoření, ideální pro krby a kamna. Výhřevnost cca 2100–2300 kWh/m³, hoří 3–4 hodiny.', 'Eichenholz mit hohem Heizwert und langer Brenndauer, ideal für Kamine und Öfen. Heizwert ca. 2100–2300 kWh/m³, brennt 3–4 Stunden.', 'Doporučeno sušit 1–2 roky na dobře větraném místě.', 'Empfohlene Trocknungszeit 1–2 Jahre an einem gut belüfteten Ort.', 'hard', 'Dub palivové dřevo', 'Eiche Brennholz', 'dub', 1, 'Tvrdé palivové dřevo', 'Hartes Brennholz', 'firewood', 'Dub', 'Eiche', 'Tvrdé palivové dřevo', 'Hartes Brennholz', '/img/eshop/dub.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (18, 1, 'palivove', 'Bukové dřevo s vysokou výhřevností a rovnoměrným hořením, ideální pro dlouhodobé vytápění. Výhřevnost cca 2100–2200 kWh/m³, hoří 2–3 hodiny.', 'Buchenholz mit hohem Heizwert und gleichmäßigem Abbrand, ideal für langanhaltendes Heizen. Heizwert ca. 2100–2200 kWh/m³, brennt 2–3 Stunden.', 'Doporučeno sušit 1–2 roky.', 'Empfohlene Trocknungszeit 1–2 Jahre.', 'hard', 'Buk palivové dřevo', 'Buche Brennholz', 'buk', 2, 'Tvrdé palivové dřevo', 'Hartes Brennholz', 'firewood', 'Buk', 'Buche', 'Tvrdé palivové dřevo', 'Hartes Brennholz', '/img/eshop/buk.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (19, 1, 'palivove', 'Břízové dřevo je oblíbené pro rovnoměrné hoření, minimální kouřivost a jemnou vůni. Skvěle se hodí pro vytápění v krbech a kamnech. Výhřevnost cca 2200–2500 kWh/m³, hoří 3–4 hodiny.', 'Beliebt für gleichmäßigen Abbrand, minimale Rauchentwicklung und einen feinen Duft. Bestens geeignet zum Heizen in Kaminen und Öfen. Heizwert ca. 2200–2500 kWh/m³, brennt 3–4 Stunden.', 'Doporučeno sušit 1–2 roky.', 'Empfohlene Trocknungszeit 1–2 Jahre.', 'hard', 'Akát palivové dřevo', 'Akazie Brennholz', 'akat', 3, 'Tvrdé palivové dřevo', 'Hartes Brennholz', 'firewood', 'Akát', 'Akazie', 'Tvrdé palivové dřevo', 'Hartes Brennholz', '/img/eshop/akat.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (20, 1, 'palivove', 'Jasanové dřevo poskytuje stabilní hoření a intenzivní teplo, vhodné pro krby i kamna. Výhřevnost cca 1900–2100 kWh/m³, hoří 2–3 hodiny.', 'Eschenholz sorgt für einen stabilen Abbrand und intensive Wärme, geeignet für Kamine und Öfen. Heizwert ca. 1900–2100 kWh/m³, brennt 2–3 Stunden.', 'Doporučeno sušit 1–2 roky.', 'Empfohlene Trocknungszeit 1–2 Jahre.', 'hard', 'Jasan palivové dřevo', 'Esche Brennholz', 'jasan', 4, 'Tvrdé palivové dřevo', 'Hartes Brennholz', 'firewood', 'Jasan', 'Esche', 'Tvrdé palivové dřevo', 'Hartes Brennholz', '/img/eshop/jasan.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (21, 1, 'palivove', 'Břízové dřevo je oblíbené pro rovnoměrné hoření, minimální kouřivost a jemnou vůni. Skvěle se hodí pro vytápění v krbech a kamnech. Výhřevnost cca 1900–2100 kWh/m³, hoří 2–3 hodiny.', 'Beliebt für gleichmäßigen Abbrand, minimale Rauchentwicklung und einen feinen Duft. Bestens geeignet zum Heizen in Kaminen und Öfen. Heizwert ca. 1900–2100 kWh/m³, brennt 2–3 Stunden.', 'Doporučeno sušit 1–2 roky.', 'Empfohlene Trocknungszeit 1–2 Jahre.', 'hard', 'Bříza palivové dřevo', 'Birke Brennholz', 'briza', 5, 'Tvrdé palivové dřevo', 'Hartes Brennholz', 'firewood', 'Bříza', 'Birke', 'Tvrdé palivové dřevo', 'Hartes Brennholz', '/img/eshop/briza.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (22, 1, 'palivove', 'Habr patří mezi nejvýhřevnější dřeva, poskytuje dlouhotrvající a intenzivní teplo. Výhřevnost cca 2300–2500 kWh/m³, hoří 3–4 hodiny.', 'Hainbuche gehört zu den heizwertstärksten Hölzern und liefert lang anhaltende, intensive Wärme. Heizwert ca. 2300–2500 kWh/m³, brennt 3–4 Stunden.', 'Doporučeno sušit 1–2 roky.', 'Empfohlene Trocknungszeit 1–2 Jahre.', 'hard', 'Habr palivové dřevo', 'Hainbuche Brennholz', 'habr', 6, 'Tvrdé palivové dřevo', 'Hartes Brennholz', 'firewood', 'Habr', 'Hainbuche', 'Tvrdé palivové dřevo', 'Hartes Brennholz', '/img/eshop/habr.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (23, 1, 'rezivo', 'Masivní dřevěné trámy určené pro konstrukce krovů, stropů a nosných částí staveb. Vyrobené z kvalitního dřeva s dlouhou životností.', 'Massive Holzbalken für Dachstühle, Decken und tragende Bauteile. Aus hochwertigem Holz mit langer Lebensdauer gefertigt.', NULL, NULL, NULL, NULL, NULL, 'tramy', 0, NULL, NULL, 'lumber', 'Trámy', 'Balken', 'I. jakostní třída', 'Güteklasse I', '/img/eshop/tramy.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (24, 1, 'rezivo', 'Stavební latě vhodné pro střešní konstrukce, rošty a další stavební aplikace. Vyrobené z kvalitního dřeva, dostupné v různých délkách a průřezech. Ideální pro přesné a spolehlivé konstrukce.', 'Bauholzlatten geeignet für Dachkonstruktionen, Roste und weitere Bauanwendungen. Aus hochwertigem Holz, erhältlich in verschiedenen Längen und Querschnitten. Ideal für präzise und zuverlässige Konstruktionen.', NULL, NULL, NULL, NULL, NULL, 'late', 1, NULL, NULL, 'lumber', 'Střešní latě', 'Dachlatten', 'I. jakostní třída', 'Güteklasse I', '/img/eshop/late.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (25, 1, 'rezivo', 'Robustní fošny ideální pro výrobu podlah, bednění nebo konstrukční prvky. Dostupné v široké škále rozměrů a tlouštěk. Kvalitní dřevo zajišťuje pevnost a odolnost.', 'Robuste Bohlen ideal für die Herstellung von Böden, Schalungen oder Konstruktionselementen. Erhältlich in einer großen Auswahl an Maßen und Stärken. Hochwertiges Holz sorgt für Festigkeit und Beständigkeit.', NULL, NULL, NULL, NULL, NULL, 'fosny', 2, NULL, NULL, 'lumber', 'Fošny', 'Bohlen', 'I. jakostní třída', 'Güteklasse I', '/img/eshop/fosny.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (26, 1, 'rezivo', 'Kvalitní stavební prkna vhodná pro bednění, podlahy a další stavební využití.', 'Hochwertige Bauschnittbretter geeignet für Schalungen, Böden und weitere Bauanwendungen.', NULL, NULL, NULL, NULL, NULL, 'prkna', 3, NULL, NULL, 'lumber', 'Prkna', 'Bretter', 'I. a II. jakostní třída', 'Güteklasse I und II', '/img/eshop/prkna.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (27, 1, 'zbytky', 'Levné a efektivní palivo z odkorněných kusů dřeva. Vhodné pro kamna, krby a kotle. Poskytuje vysokou výhřevnost při minimálních nákladech. Nabízíme volně ložené nebo balené dle potřeb zákazníka.', 'Günstiger und effizienter Brennstoff aus entrindeten Holzstücken. Geeignet für Öfen, Kamine und Heizkessel. Bietet hohen Heizwert bei minimalen Kosten. Erhältlich lose oder verpackt nach Kundenwunsch.', NULL, NULL, NULL, NULL, NULL, 'odkory', 0, NULL, NULL, 'simple_variant', 'Odkory na topení', 'Rindenreste zum Heizen', 'Odkory', 'Rindenreste', '/img/eshop/odkory.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (28, 1, 'zbytky', 'Kvalitní dřevěné piliny vhodné pro podestýlku, mulčování nebo lisování briket. Nízká vlhkost a jemná struktura zaručují snadnou manipulaci. Nabízíme volně ložené nebo balené varianty.', 'Hochwertiges Sägemehl geeignet als Einstreu, zum Mulchen oder zum Pressen von Briketts. Niedrige Feuchtigkeit und feine Struktur sorgen für einfache Handhabung. Erhältlich lose oder verpackt.', NULL, NULL, NULL, NULL, NULL, 'piliny', 1, NULL, NULL, 'simple_variant', 'Piliny', 'Sägemehl', 'Piliny', 'Sägemehl', '/img/eshop/piliny.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (29, 1, 'zbytky', 'Dřevní štěpka ideální jako ekologické palivo nebo mulčovací materiál pro zahrady. Vyrobená z kvalitního dřeva, nízká vlhkost zajišťuje vysokou výhřevnost. Dostupná ve volně ložené či balené podobě.', 'Holzhackschnitzel, ideal als umweltfreundlicher Brennstoff oder Mulchmaterial für den Garten. Aus hochwertigem Holz hergestellt, niedrige Feuchtigkeit sorgt für hohen Heizwert. Erhältlich lose oder verpackt.', NULL, NULL, NULL, NULL, NULL, 'stepka', 2, NULL, NULL, 'simple_variant', 'Štěpka', 'Hackschnitzel', 'Štěpka', 'Hackschnitzel', '/img/eshop/stepka.webp');
INSERT INTO catalog_products (id, active, category, description, description_de, drying_note, drying_note_de, hardness, image_alt, image_alt_de, key, position, subtitle, subtitle_de, template, title, title_de, type_label, type_label_de, image) VALUES (30, 1, 'kamenivo', 'Přírodní okrasné kamenivo pro úpravu zahrad, obsypy ploch a dekorativní účely. Dostupné ve třech frakcích.', 'Natürliche Ziersteine für die Gartengestaltung, Flächenschüttungen und dekorative Zwecke. Erhältlich in drei Körnungen.', NULL, NULL, NULL, NULL, NULL, 'okrasne_kamenivo', 3, NULL, NULL, 'simple_variant', 'Okrasné kamenivo', 'Ziersteine', 'Kamenivo', 'Kies', '/img/eshop/kamenivo.webp');
