INSERT INTO reviews (id, avatar, name, position, reviewed_on, stars, text) VALUES (5, 'reviews/divispoutnik.webp', 'Diviš poutník z Milfrau', 1, '2026-09-13', 5, 'Byl jsem velmi překvapen. Ochota, vstřícnost a zboží jsme obdrželi dříve než bylo původně naplánováno.');
INSERT INTO reviews (id, avatar, name, position, reviewed_on, stars, text) VALUES (6, 'reviews/pistadebef.webp', 'Pišta Debef', 2, '2023-11-13', 5, 'Bez problémů, z katru trámy aji nejsou moc vymačkané a řez je poměrně hladký oproti jiné pile.');
