INSERT INTO services (id, button_path, button_text, button_text_de, content, content_de, images, title, title_de) VALUES (6, '/kontakt#kalkulace', 'Ceník kalkulace', 'Preisliste Kalkulation', 'Nabízíme nezávaznou cenovou kalkulaci našich výrobků a služeb, která vám pomůže lépe se rozhodnout před nákupem. <br /><br /> Díky přesné ceně předem víte, co vás čeká – bez závazků a bez překvapení.', 'Wir bieten eine unverbindliche Preiskalkulation unserer Produkte und Dienstleistungen an, die Ihnen die Kaufentscheidung erleichtert. <br /><br /> Dank des genauen Preises im Voraus wissen Sie, was Sie erwartet – ohne Verpflichtungen und ohne Überraschungen.', '[]', 'Cenová kalkulace', 'Preiskalkulation');
INSERT INTO services (id, button_path, button_text, button_text_de, content, content_de, images, title, title_de) VALUES (7, '/sluzby#doprava', 'Ceník dopravy', 'Preisliste Lieferung', 'Na přání vám zpracované výrobky bezpečně doručíme až na místo určení. Rozvážíme palivové dřevo, kulatinu i řezivo – vše dopravíme ihned po výrobě, abyste měli materiál co nejdříve k dispozici. <br /><br />Doba výroby a následná doprava se odvíjí od rozsahu objednávky. O přesném termínu dodání vás vždy informujeme předem. <br /><br />Rozvoz zajišťujeme vlastním vozovým parkem – nákladním vozem MAN TGM 15.250 a soupravou Scania G450 s hydraulickou rukou pro přepravu kulatiny přímo z lesa.', 'Auf Wunsch liefern wir die fertigen Produkte sicher direkt an Ihren Bestimmungsort. Wir liefern Brennholz, Rundholz und Schnittholz – alles wird sofort nach der Fertigung transportiert, damit Sie das Material so schnell wie möglich erhalten. <br /><br />Die Fertigungs- und anschließende Lieferzeit richtet sich nach dem Umfang der Bestellung. Über den genauen Liefertermin informieren wir Sie stets im Voraus. <br /><br />Die Auslieferung erfolgt mit unserem eigenen Fuhrpark – dem LKW MAN TGM 15.250 und dem Scania G450 mit Hydraulikarm für den Transport von Rundholz direkt aus dem Wald.', '["sluzby/doprava1.webp","sluzby/doprava2.webp"]', 'Doprava', 'Lieferung');
INSERT INTO services (id, button_path, button_text, button_text_de, content, content_de, images, title, title_de) VALUES (8, '/sluzby#impregnace', 'Ceník impregnace', 'Preisliste Imprägnierung', 'Nabízíme možnost profesionální impregnace vašich dřevěných výrobků, a to pomocí moderní technologie v naší impregnační vaně. Impregnace výrazně prodlužuje životnost dřeva a chrání ho proti vlhkosti, škůdcům i houbám. <br /><br />Na přání zákazníka impregnujeme jakýkoli náš výrobek. Vše provádíme pečlivě a s důrazem na kvalitu výsledné ochrany.', 'Wir bieten die professionelle Imprägnierung Ihrer Holzprodukte mittels moderner Technologie in unserer Imprägnierwanne an. Die Imprägnierung verlängert die Lebensdauer des Holzes erheblich und schützt es vor Feuchtigkeit, Schädlingen und Pilzen. <br /><br />Auf Kundenwunsch imprägnieren wir jedes unserer Produkte. Wir arbeiten stets sorgfältig und mit Fokus auf die Qualität des Schutzes.', '["sluzby/impregnace1.webp","sluzby/impregnace2.webp"]', 'Impregnace', 'Imprägnierung');
INSERT INTO services (id, button_path, button_text, button_text_de, content, content_de, images, title, title_de) VALUES (9, '/sluzby#hoblovani', 'Ceník hoblování', 'Preisliste Hobeln', 'Nabízíme možnost ohoblování dřevěného materiálu přesně podle vašich požadavků. Disponujeme výkonnou hoblovačkou s hoblovacím průřezem až 80 cm, která si poradí i s rozměrnějšími kusy.<br><br>Hoblujeme nejčastěji fošny, prkna a hranoly libovolné délky. Zákazník si může určit, která strana bude pohledová, a hloubku úběru. Každý kus zpracováváme pečlivě, s důrazem na kvalitu povrchu a preciznost provedení.', 'Wir bieten das Hobeln von Holzmaterial genau nach Ihren Vorgaben an. Wir verfügen über eine leistungsstarke Hobelmaschine mit einem Hobelquerschnitt bis 80 cm, die auch größere Werkstücke bewältigt.<br><br>Am häufigsten hobeln wir Bohlen, Bretter und Kanthölzer beliebiger Länge. Der Kunde kann bestimmen, welche Seite die Sichtseite sein soll, sowie die Abtragstiefe. Jedes Stück bearbeiten wir sorgfältig, mit Fokus auf Oberflächenqualität und Präzision.', '["sluzby/hoblovani1.webp","sluzby/hoblovani2.webp"]', 'Hoblování', 'Hobeln');
INSERT INTO services (id, button_path, button_text, button_text_de, content, content_de, images, title, title_de) VALUES (10, '/sluzby#porez-prodej-kulatiny', 'Ceník pořezu', 'Preisliste Sägen', 'Na základě vaší žádosti nabízíme možnost pořezání vaší vlastní kulatiny na míru podle požadovaných rozměrů. Pokud nemáte zájem o další zpracování, je možné kulatinu také jednoduše prodat přímo nám. <br /><br /> Tato služba je ideální pro soukromé vlastníky lesa, malé firmy nebo kohokoli, kdo chce efektivně využít vlastní dřevo bez starostí s technickým vybavením.', 'Auf Ihren Wunsch bieten wir das Sägen Ihres eigenen Rundholzes nach Maß gemäß den gewünschten Abmessungen an. Wenn Sie an einer weiteren Verarbeitung nicht interessiert sind, können Sie das Rundholz auch einfach direkt an uns verkaufen. <br /><br /> Dieser Service ist ideal für private Waldbesitzer, kleine Unternehmen oder jeden, der sein eigenes Holz effizient nutzen möchte, ohne sich um technische Ausrüstung kümmern zu müssen.', '["sluzby/kulatina1.webp","sluzby/kulatina2.webp"]', 'Pořez / Prodej kulatiny', 'Sägen / Verkauf von Rundholz');
INSERT INTO faq_items (id, content, content_de, image, title, title_de) VALUES (4, 'Cena dopravy se odvíjí od vzdálenosti a množství objednaného dřeva.<br>Po předání adresy a požadovaného množství vám vždy spočítáme přesnou cenu, aby byla pro vás co nejvýhodnější.', 'Der Lieferpreis richtet sich nach Entfernung und bestellter Holzmenge.<br>Nach Angabe der Adresse und der gewünschten Menge berechnen wir Ihnen stets den genauen Preis, damit er für Sie möglichst günstig ist.', 'co-by-vas-mohlo-zajimat/nakladak.webp', 'Kolik stojí doprava?', 'Was kostet die Lieferung?');
INSERT INTO faq_items (id, content, content_de, image, title, title_de) VALUES (5, '1. Výkonná Scania G450 s hydraulickou rukou určená pro profesionální přepravu kulatiny a manipulaci se dřevem přímo v lese i na skladech.<br>2. Hydraulický jeřáb umožňuje samostatnou nakládku i vykládku bez potřeby další manipulační techniky, což výrazně urychluje celý proces.', '1. Die leistungsstarke Scania G450 mit Hydraulikarm ist für den professionellen Transport von Rundholz und die Handhabung von Holz direkt im Wald und auf Lagerplätzen bestimmt.<br>2. Der Hydraulikkran ermöglicht selbstständiges Be- und Entladen ohne zusätzliche Umschlagtechnik, was den gesamten Prozess deutlich beschleunigt.', 'co-by-vas-mohlo-zajimat/scania.webp', 'Scania G450 + HR', 'Scania G450 + HR');
INSERT INTO faq_items (id, content, content_de, image, title, title_de) VALUES (6, '1. Moderní nákladní vůz MAN určený pro efektivní rozvoz palivového dřeva zákazníkům po celé České republice.<br>2. Přeprava 1 až 2 kontejnerů najednou o objemu 5 až 25 m³, což umožňuje rozvoz více objednávek během jedné jízdy.', '1. Moderner MAN-Lastwagen für die effiziente Auslieferung von Brennholz an Kunden in der ganzen Tschechischen Republik.<br>2. Transport von 1 bis 2 Containern gleichzeitig mit einem Volumen von 5 bis 25 m³, was die Auslieferung mehrerer Bestellungen in einer Fahrt ermöglicht.', 'co-by-vas-mohlo-zajimat/man-tgm.webp', 'MAN TGM 15.250', 'MAN TGM 15.250');
